// ========================================================================
// Step 1: Run subscription detection
// ========================================================================
// This calls the detection logic inline (same algorithm as
// scripts/detect-subscriptions.js) via Plaid transactions already synced
// in Neon.  We do the detection first, then query the results.
//
// Since n8n Code nodes can't import external modules on Community Edition,
// we call the detection script via the Execute Command node instead.
// This Code node just returns a passthrough signal.
// ========================================================================
return [{ json: { trigger: 'digest' } }];

// ========================================================================
// Build the weekly digest email body (mobile-optimized)
// ========================================================================
const subs = $input.all().map(i => i.json);

// Email wrapper with responsive meta + dark mode styles
const emailHead = '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><meta name="color-scheme" content="dark"><meta name="supported-color-schemes" content="dark"><style>body,html{margin:0;padding:0;-webkit-text-size-adjust:100%;-ms-text-size-adjust:100%}@media only screen and (max-width:480px){.email-body{padding:24px 16px !important}.email-header{padding:28px 16px 24px !important}.email-header h1{font-size:24px !important}.cost-value{font-size:24px !important}.sub-table td,.sub-table th{padding:8px 6px !important;font-size:12px !important}.card{padding:14px 16px !important}.footer{padding:16px !important}}</style></head><body style="margin:0;padding:0;background:#06080e;">';
const emailFoot = '</body></html>';

if (subs.length === 0) {
  return [{ json: { subject: 'Subscription Digest \u2014 No Active Subscriptions', body: emailHead + '<div style="font-family:Inter,system-ui,-apple-system,Helvetica,Arial,sans-serif;background:#080b12;color:#f0ebe3;max-width:600px;margin:0 auto;"><div class="email-header" style="padding:40px 32px 32px;"><h2 style="font-weight:300;font-size:28px;letter-spacing:-0.3px;margin:0 0 8px;color:#f0ebe3;">Weekly Digest</h2><p style="color:#78746d;font-size:15px;font-weight:300;margin:0;">No recurring subscriptions detected yet. Transactions may still be syncing.</p></div></div>' + emailFoot } }];
}

let monthlyTotal = 0;
for (const s of subs) {
  const amt = parseFloat(s.amount);
  if (s.cadence_days <= 35) monthlyTotal += amt;
  else if (s.cadence_days <= 65) monthlyTotal += amt / 2;
  else if (s.cadence_days <= 95) monthlyTotal += amt / 3;
  else monthlyTotal += amt / (s.cadence_days / 30);
}

const newSubs = subs.filter(s => s.is_new);
const changedSubs = subs.filter(s => s.amount_changed);

const fmt = (n) => '$' + parseFloat(n).toFixed(2);
const fmtDate = (d) => d ? new Date(d).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : '\u2014';

let html = emailHead;
html += '<div style="font-family:Inter,system-ui,-apple-system,Helvetica,Arial,sans-serif;background:#080b12;max-width:600px;margin:0 auto;border-radius:12px;overflow:hidden;">';

// Header
html += '<div class="email-header" style="background:linear-gradient(135deg,#2a1f1a 0%,#121a1a 50%,#080b12 100%);padding:40px 32px 32px;">';
html += '<p style="font-size:10px;font-weight:500;letter-spacing:2px;text-transform:uppercase;color:#78746d;margin:0 0 16px;">Subscription Tracker</p>';
html += '<h1 style="font-size:32px;font-weight:300;color:#f0ebe3;margin:0 0 8px;letter-spacing:-0.5px;">Weekly Digest</h1>';
html += '<p style="font-size:15px;color:#78746d;margin:0;font-weight:300;">' + subs.length + ' active subscription' + (subs.length !== 1 ? 's' : '') + ' tracked</p>';
html += '</div>';

// Monthly cost
html += '<div class="email-body" style="padding:0 32px;">';
html += '<div class="card" style="background:#111519;border:1px solid #1e2228;border-radius:10px;padding:20px 24px;margin:24px 0;">';
html += '<p style="font-size:10px;letter-spacing:1.5px;text-transform:uppercase;color:#78746d;margin:0 0 6px;font-weight:500;">Estimated Monthly Cost</p>';
html += '<p class="cost-value" style="font-size:28px;font-weight:300;color:#c8856c;margin:0;letter-spacing:-0.5px;">' + fmt(monthlyTotal) + '</p>';
html += '</div>';

// New subs callout
if (newSubs.length > 0) {
  html += '<div class="card" style="background:#0f1a14;border:1px solid #1a2e20;border-radius:10px;padding:16px 20px;margin:16px 0;">';
  html += '<p style="font-size:10px;letter-spacing:1.5px;text-transform:uppercase;color:#6fcf97;margin:0 0 10px;font-weight:600;">New This Week</p>';
  for (const s of newSubs) {
    html += '<p style="font-size:14px;color:#f0ebe3;margin:4px 0;font-weight:300;">' + s.display_name + ' \u2014 ' + fmt(s.amount) + ' every ' + s.cadence_days + ' days</p>';
  }
  html += '</div>';
}

// Price changes callout
if (changedSubs.length > 0) {
  html += '<div class="card" style="background:#1a1810;border:1px solid #2e2816;border-radius:10px;padding:16px 20px;margin:16px 0;">';
  html += '<p style="font-size:10px;letter-spacing:1.5px;text-transform:uppercase;color:#f0c36d;margin:0 0 10px;font-weight:600;">Price Changes</p>';
  for (const s of changedSubs) {
    const delta = parseFloat(s.amount) - parseFloat(s.prior_amount);
    const arrow = delta > 0 ? '\u2191' : '\u2193';
    const dColor = delta > 0 ? '#eb6b6b' : '#6fcf97';
    html += '<p style="font-size:14px;color:#f0ebe3;margin:4px 0;font-weight:300;">' + s.display_name + ': ' + fmt(s.prior_amount) + ' \u2192 ' + fmt(s.amount) + ' <span style="color:' + dColor + ';">(' + arrow + fmt(Math.abs(delta)) + ')</span></p>';
  }
  html += '</div>';
}

// Subscription table (3 columns: Name+Cycle, Amount, Next)
html += '<table class="sub-table" style="width:100%;border-collapse:collapse;margin:24px 0;" cellpadding="0" cellspacing="0">';
html += '<tr><th style="text-align:left;padding:10px 12px;font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:#78746d;font-weight:500;border-bottom:1px solid #1e2228;">Subscription</th><th style="text-align:right;padding:10px 12px;font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:#78746d;font-weight:500;border-bottom:1px solid #1e2228;">Amount</th><th style="text-align:right;padding:10px 12px;font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:#78746d;font-weight:500;border-bottom:1px solid #1e2228;">Next</th></tr>';
for (const s of subs) {
  const cadenceLabel = s.cadence_days <= 35 ? 'Monthly' : s.cadence_days <= 65 ? 'Bi-monthly' : s.cadence_days <= 95 ? 'Quarterly' : s.cadence_days <= 370 ? 'Yearly' : s.cadence_days + 'd';
  html += '<tr>';
  html += '<td style="padding:12px;font-size:14px;font-weight:300;color:#f0ebe3;border-bottom:1px solid #0e1115;">' + s.display_name + ' <span style="font-size:11px;color:#5a5650;">' + cadenceLabel + '</span></td>';
  html += '<td style="padding:12px;font-size:14px;font-weight:400;color:#d4a574;text-align:right;border-bottom:1px solid #0e1115;">' + fmt(s.amount) + '</td>';
  html += '<td style="padding:12px;font-size:13px;font-weight:300;color:#78746d;text-align:right;border-bottom:1px solid #0e1115;">' + fmtDate(s.next_expected) + '</td>';
  html += '</tr>';
}
html += '</table></div>';

// Footer
html += '<div class="footer" style="padding:24px 32px 32px;border-top:1px solid #141820;">';
html += '<p style="color:#3a3834;font-size:11px;margin:0;font-weight:300;letter-spacing:0.3px;">Generated by Subscription Tracker</p>';
html += '</div></div>';
html += emailFoot;

const resetSql = 'UPDATE detected_subscriptions SET is_new = false, amount_changed = false WHERE is_active = true;';

return [{ json: {
  subject: 'Subscription Digest \u2014 ' + subs.length + ' active, ' + fmt(monthlyTotal) + '/mo',
  body: html,
  resetSql,
  subCount: subs.length,
  monthlyTotal: monthlyTotal.toFixed(2),
} }];
